import json
from pathlib import Path
import numpy as np
from sklearn.ensemble import RandomForestClassifier
from sklearn.preprocessing import StandardScaler


class WineService:
    def __init__(self, algorithm=None):
        self.algorithm = algorithm or json.loads(Path(__file__).with_name('config.json').read_text())['algorithm']
        if self.algorithm not in ('random_forest', 'centroid'):
            raise ValueError('Unsupported algorithm: ' + str(self.algorithm))
        self.model = None
        self.rf = None
        self.scaler = None
        self.classes = None
        self.centers = None
        self.classes_ = None

    def _validate_X(self, X):
        try:
            arr = np.asarray(X, dtype=float)
        except (TypeError, ValueError) as exc:
            raise ValueError('Expected finite [n, 13] features') from exc
        if arr.ndim != 2 or arr.shape[1] != 13 or not np.isfinite(arr).all():
            raise ValueError('Expected finite [n, 13] features')
        return arr

    def fit(self, X, y):
        X = self._validate_X(X)
        try:
            y = np.asarray(y)
        except (TypeError, ValueError) as exc:
            raise ValueError('Expected matching one-dimensional labels') from exc
        if y.ndim != 1 or y.shape[0] != X.shape[0]:
            raise ValueError('Expected matching one-dimensional labels')
        try:
            y = y.astype(int)
        except (TypeError, ValueError) as exc:
            raise ValueError('Expected integer labels') from exc
        if X.shape[0] == 0:
            raise ValueError('Cannot fit with no samples')

        self.model = None
        self.rf = None
        self.scaler = None
        self.classes = None
        self.centers = None
        self.classes_ = None

        if self.algorithm == 'random_forest':
            model = RandomForestClassifier(
                n_estimators=300,
                random_state=42,
                n_jobs=1,
            )
            model.fit(X, y)
            self.model = model
            self.rf = model
            self.classes_ = model.classes_
        else:
            scaler = StandardScaler().fit(X)
            z = scaler.transform(X)
            classes = np.unique(y)
            centers = np.array([z[y == label].mean(axis=0) for label in classes])
            self.scaler = scaler
            self.classes = classes
            self.centers = centers
            self.classes_ = classes
        return self

    def predict(self, X):
        try:
            n = len(X)
        except TypeError as exc:
            raise ValueError('Expected finite [n, 13] features') from exc
        if n == 0:
            return []
        X = self._validate_X(X)

        if self.algorithm == 'random_forest':
            if self.model is None:
                raise ValueError('Model has not been fitted')
            probabilities = self.model.predict_proba(X)
            indices = probabilities.argmax(axis=1)
            labels = self.model.classes_[indices]
            confidences = probabilities[np.arange(len(indices)), indices]
            return [
                {
                    'label': int(labels[i]),
                    'confidence': float(min(1.0, max(0.0, confidences[i]))),
                    'metadata': {
                        'algorithm': self.algorithm,
                        'reason': 'sklearn RandomForestClassifier predict_proba',
                    },
                }
                for i in range(len(indices))
            ]

        if self.scaler is None:
            raise ValueError('Model has not been fitted')
        distances = ((self.scaler.transform(X)[:, None] - self.centers) ** 2).sum(axis=2)
        probabilities = np.exp(-(distances - distances.min(axis=1, keepdims=True)))
        probabilities /= probabilities.sum(axis=1, keepdims=True)
        return [
            {
                'label': int(self.classes[p.argmax()]),
                'confidence': float(p.max()),
                'metadata': {
                    'algorithm': self.algorithm,
                    'reason': 'standardized nearest centroid',
                },
            }
            for p in probabilities
        ]
